using System;using System.IO;using System.Reflection;using SargasPC;
class AutonomyTests {
 static int n;static void Check(bool x){if(!x)throw new Exception("auto "+n);n++;}
 static string Run(Core c,Func<string> u,Func<string> d){try{return (string)typeof(Core).GetMethod("RunScheduledUpdate",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(c,new object[]{u,d});}catch(TargetInvocationException e){throw e.InnerException;}}
 static void Main(){long now=DateTime.UtcNow.Ticks;var s=new Settings();Check(!AutonomyPolicy.UpdateDue(s,now));s.AutoDbUpdate=true;Check(AutonomyPolicy.UpdateDue(s,now));s.AutoDbSuccessAt=now;Check(!AutonomyPolicy.UpdateDue(s,now));s.AutoDbSuccessAt=now-TimeSpan.FromHours(24).Ticks;Check(AutonomyPolicy.UpdateDue(s,now));s.AutoDbAttemptAt=now;s.AutoDbFailures=1;Check(!AutonomyPolicy.UpdateDue(s,now));s.AutoDbAttemptAt=now-TimeSpan.FromMinutes(30).Ticks;Check(AutonomyPolicy.UpdateDue(s,now));s.AutoDbFailures=2;Check(!AutonomyPolicy.UpdateDue(s,now));s.AutoDbAttemptAt=now-TimeSpan.FromHours(1).Ticks;Check(AutonomyPolicy.UpdateDue(s,now));Check(AutonomyPolicy.RetryDelay(100)==TimeSpan.FromHours(6).Ticks);Check(AutonomyPolicy.RetryDelay(-1)==TimeSpan.FromMinutes(30).Ticks);s.AutoDbAttemptAt=now+1;Check(!AutonomyPolicy.UpdateDue(s,now));Check(AutonomyPolicy.Status(s,now).Contains("ateityje"));s.AutoDbAttemptAt=0;s.AutoDbSuccessAt=now+1;Check(!AutonomyPolicy.UpdateDue(s,now));s.AutoDbSuccessAt=0;Check(!AutonomyPolicy.UpdateDue(s,0));
 string root=Path.Combine(Path.GetTempPath(),"autonomy-"+Guid.NewGuid());try{var c=new Core(root);c.Config.AutoDbUpdate=true;c.Config.EngineDetectionAt=now;int updates=0,controls=0;string report=Run(c,()=>{updates++;return "updated";},()=>{controls++;return "control";});Check(updates==1&&controls==0);Check(c.Config.AutoDbSuccessAt>0&&c.Config.AutoDbFailures==0);Check(c.Config.EngineDetectionAt==0);Check(!AutonomyPolicy.UpdateDue(new Core(root).Config,DateTime.UtcNow.Ticks));c.Reset();c.Config.AutoDetectionControl=true;Run(c,()=>"updated",()=>{controls++;c.Config.EngineDetectionAt=DateTime.UtcNow.Ticks;return "controlled";});Check(controls==1&&c.Config.EngineDetectionAt>0);c.Reset();Run(c,()=>{throw new IOException("network unavailable");},()=>{controls++;return "unexpected";});Check(c.Config.AutoDbSuccessAt==0&&c.Config.EngineDetectionAt==0);Check(c.Config.AutoDbFailures==1&&c.NotChecked==1);Check(controls==1);Check(!AutonomyPolicy.UpdateDue(new Core(root).Config,DateTime.UtcNow.Ticks));c.Reset();Run(c,()=>"updated",()=>{throw new IOException("control intercepted");});Check(c.Config.AutoDbSuccessAt>0&&c.Config.EngineDetectionAt==0&&c.NotChecked==1);Check(c.Config.AutoDbFailures==0);c.Reset();bool cancelled=false;try{Run(c,()=>{throw new OperationCanceledException();},()=>"x");}catch(OperationCanceledException){cancelled=true;}Check(cancelled);Check(c.Config.AutoDbFailures==1&&c.Config.AutoDbSuccessAt==0);c.Config.RestoreWatch=true;c.Config.SavedWatchEnabled=true;c.Config.SavedAutoQuarantine=true;c.Config.SavedWatchDirectory=Path.Combine(root,"personal");c.SaveSettings();var saved=new Core(root).Config;Check(saved.RestoreWatch&&saved.SavedWatchEnabled&&saved.SavedAutoQuarantine&&saved.SavedWatchDirectory==c.Config.SavedWatchDirectory);
 c.Reset();c.Config.AutoDbFailures=int.MaxValue;Run(c,()=>{throw new IOException("failure");},()=>"unexpected");Check(c.Config.AutoDbFailures==12);Console.WriteLine("PASS: "+n+" autonomy checks (scheduling, retry, persistence, failure/cancel/control separation; simulated updates, not live FreshClam).");}finally{Directory.Delete(root,true);}}
}
